draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
const cy = H * 0.62;
const s = Math.min(W / 3.4, H) * 0.46;

function label(x, y, txt) { ctx.fillStyle = C.ink; ctx.fillText(txt, x, y); }
function dot(x, y) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(x, y, 4, 0, 6.284); ctx.fill();
}

// ---- half disk ----
let cx = W * 0.18;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, s, Math.PI, 0); ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx - s - 6, cy); ctx.lineTo(cx + s + 6, cy); ctx.stroke();
dot(cx, cy - 4 * s / (3 * Math.PI));
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy - 4 * s / (3 * Math.PI)); ctx.stroke();
label(cx, cy + 20, "half disk");
ctx.fillStyle = C.accent;
ctx.fillText("4R / 3pi = 0.424 R", cx, cy + 38);
ctx.fillStyle = C.faint;
ctx.fillText("R", cx + s * 0.55, cy - 6);

// ---- solid hemisphere ----
cx = W * 0.5;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, s, Math.PI, 0); ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx - s - 6, cy); ctx.lineTo(cx + s + 6, cy); ctx.stroke();
ctx.strokeStyle = C.paper; ctx.lineWidth = 1;
for (let i = 1; i < 5; i++) {
  const yy = cy - s * i / 5;
  const hw = Math.sqrt(Math.max(s * s - (cy - yy) * (cy - yy), 0));
  ctx.beginPath(); ctx.moveTo(cx - hw, yy); ctx.lineTo(cx + hw, yy); ctx.stroke();
}
dot(cx, cy - 3 * s / 8);
ctx.strokeStyle = C.accent; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy - 3 * s / 8); ctx.stroke();
label(cx, cy + 20, "solid hemisphere");
ctx.fillStyle = C.accent;
ctx.fillText("3R / 8 = 0.375 R", cx, cy + 38);

// ---- solid cone ----
cx = W * 0.82;
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.moveTo(cx - s * 0.75, cy); ctx.lineTo(cx + s * 0.75, cy); ctx.lineTo(cx, cy - s);
ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx - s - 6, cy); ctx.lineTo(cx + s + 6, cy); ctx.stroke();
dot(cx, cy - s / 4);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, cy - s / 4); ctx.stroke();
label(cx, cy + 20, "solid cone");
ctx.fillStyle = C.accent;
ctx.fillText("h / 4 above the base", cx, cy + 38);
ctx.fillStyle = C.faint;
ctx.fillText("h", cx + 10, cy - s * 0.7);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("each dot is the centre of mass; the flat face is the reference line", 10, H * 0.10);
